            This is a simple example of getting the intersection of two polygons.
            
using System;
using System.Collections.Generic;
using System.Text;

using WW.Math;
using WW.Math.Geometry;

namespace WW.Test {
    public class Polygon2DTest {
        public List<Polygon2D> IntersectionExample() {
            // Two polygons where two edges overlap, and two edges intersect.
            Polygon2D p1 = new Polygon2D(
                new Point2D(1d, 1d),
                new Point2D(2d, 1d),
                new Point2D(2d, 2d),
                new Point2D(1d, 2d)
            );
            Polygon2D p2 = new Polygon2D(
                new Point2D(1.5d, 1.5d),
                new Point2D(2d, 1.6d),
                new Point2D(2d, 3d),
                new Point2D(1d, 3d)
            );
            List<Polygon2D> result = Polygon2D.GetIntersection(new Polygon2D[] { p1 }, new Polygon2D[] { p2 });
            return result;
        }
    }
}

